t = (HERE / 'script-v3.md').read_text()
for code, sh, a, b, *_ in S:
    blk = t.split(f'‹{sh}›', 1)[1].split('\n‹', 1)[0]
    assert t.count(a) == 1 and a in blk, (code, sh, t.count(a))
    t = t.replace(a, b)
t = t.replace('— lời v3 (sau kiểm mù vòng 1 + REVIEWER vòng 1)', '— lời v4 KHOÁ 18/10/2026 (G1 duyệt 09:35; sau kiểm mù 2 vòng + REVIEWER 2 vòng)')
(HERE.parent / 'script-v4-KHOA.md').write_text(t)
